500	/*  Completion rules                                                          */
501	/* -------------------------------------------------------------------------- */
502	
503	/**
504	 * Whether an item must be answered for the conversation to be "completed".
505	 *  - 'skipped' items never count.
506	 *  - a `note` without `requiresAck` is purely informational and never blocks.
507	 */
508	export function itemCountsTowardCompletion(item: Item): boolean {
509	  if (item.status === 'skipped') return false;
510	  if (item.kind === 'note' && !item.requiresAck) return false;
511	  return true;
512	}
513	
514	/**
515	 * Recompute the overall conversation status from its items.
516	 *
517	 *  - 'completed'   : there is at least one counting item and ALL counting
518	 *                    items are 'answered'.
519	 *  - 'in_progress' : at least one item is 'answered' (but not all).
520	 *  - 'pending'     : otherwise.
521	 *
522	 * 'archived' is a manual/terminal state, never produced here.
523	 */
524	export function computeStatus(items: Item[]): ConversationStatus {
525	  const counting = items.filter(itemCountsTowardCompletion);
526	  const answered = counting.filter((item) => item.status === 'answered');
527	
528	  if (counting.length > 0 && answered.length === counting.length) {
529	    return 'completed';
530	  }
531	  if (items.some((item) => item.status === 'answered')) {
532	    return 'in_progress';
533	  }
534	  return 'pending';
535	}
536	
537	/**
538	 * SINGLE SOURCE OF TRUTH for "does this conversation still need human
539	 * attention" (dashboard open counts, project tiles, the "open" tab filter).
540	 * A conversation closed by the second-brain bridge's raccord A
541	 * (bridge/watch.ExternalResolve.ts, RA-AC-18 — an approval resolved outside
542	 * the hub, e.g. the app) never gets its items answered: the identity guard
543	 * (server/services/identityGuard.ts) forbids the agent path from ever writing
544	 * an item `response`, so `status` stays 'pending' forever even though nothing
545	 * is actually awaiting the user. `agentFollowupStatus === 'handled'` is the
546	 * one closing signal that write path IS allowed to set — treat it as
547	 * equivalent to completion here rather than in the write path.
548	 */
549	export function isConversationOpen(
550	  m: Pick<ConversationMeta, 'status' | 'agentFollowupStatus'>
551	): boolean {
552	  return m.status !== 'completed' && m.status !== 'archived' && m.agentFollowupStatus !== 'handled';
553	}
554	
555	/**
556	 * The `ConversationStatus` to DISPLAY (StatusPill, badges) — distinct from
557	 * the raw persisted `status`. A conversation closed via the bridge's raccord
558	 * A keeps `status: 'pending'`/`'in_progress'` forever (see isConversationOpen
559	 * above): showing that raw status would badge an already-resolved
560	 * conversation as still needing the user's attention.
561	 */
562	export function effectiveConversationStatus(
563	  m: Pick<ConversationMeta, 'status' | 'agentFollowupStatus'>
564	): ConversationStatus {
565	  if (!isConversationOpen(m) && (m.status === 'pending' || m.status === 'in_progress')) {
566	    return 'completed';
567	  }
568	  return m.status;
569	}

