/* ------------------------------------------------------------------------ */
/*  Chemin A content-replacement graft — real unrelated-histories bug fix   */
/* ------------------------------------------------------------------------ */

/**
 * Pushes `branch` as a fully ORPHAN snapshot commit — a brand-new,
 * from-scratch git repo with NO relation whatsoever to `bareRepo`'s history
 * — onto `bareRepo`, reproducing EXACTLY what `transportImproveBranch` does
 * in production (re-push a real `improve/*` branch byte-for-byte from the
 * cargo remote, which never shared history with `claude-skills` to begin
 * with). Unlike `pushBranchFrom` (which branches FROM `bareRepo`'s own
 * history and therefore can never reproduce the real bug), `git merge-base`
 * between this branch and `main` returns nothing — the same empirically
 * verified signature as the two real proposals that failed on 2026-07-29
 * (chip `2026-07-29-fix-git-merge-unrelated-histories-failure-in-apply-ts-rail`).
 */
async function pushOrphanSnapshotBranch(
  bareRepo: string,
  branch: string,
  files: Record<string, string>,
): Promise<string> {
  const scratch = await mkdtemp(path.join(os.tmpdir(), 'wsapply-orphan-'));
  try {
    git(['init', '-q', '-b', branch, scratch]);
    git(['config', 'user.email', 'cloud-routine@workstation-night-cargo.local'], scratch);
    git(['config', 'user.name', 'cloud-routine'], scratch);
    await writeFiles(scratch, files);
    git(['add', '-A'], scratch);
    git(['commit', '-q', '-m', `fixture: orphan snapshot ${branch}`], scratch);
    git(['push', '-q', bareRepo, `${branch}:${branch}`], scratch);
    return gitOut(['rev-parse', branch], scratch);
  } finally {
    await rm(scratch, { recursive: true, force: true });
  }
}

