  const branchSha = await pushOrphanSnapshotBranch(bareRepo, branch, {

    // pour `invalidReplays` ci-dessus — le candidat a quitté le pool
    // local_only gouverné entre le paiement du verdict et cette
    // relecture. Neutralisé en `orphaned` (jamais réappliqué en
    // contournant `allowedProjects`/`reviewSince`, jamais silencieux).
    await writeJudgeLocalMarker(replay.markerPath, replay.candidateId, 'orphaned');
    gaps.push(
      `${replay.candidateId} : verdict payé (${replay.item.kind}) jamais appliqué, candidat désormais introuvable dans le pool local_only gouverné — marqueur neutralisé, vérifier manuellement si une application manuelle est encore pertinente`,
    );
    outcomes.push(`${replay.candidateId} : verdict payé orphelin — neutralisé (candidat introuvable)`);
    continue;
  }

  // Fix P2 (revue adversariale round 3, l.2775-2802, signalé 2× — "la
  // boucle de rejeu ignore maxAttempts") : les sœurs de cette boucle
  // (sessions irrésolubles ci-dessus, `invalidReplays` juste au-dessus)
  // bornent déjà un candidat déjà abandonné AVANT cette invocation —
  // celle-ci seule ne le faisait pas, un candidat dont l'APPLICATION
  // reste durablement en échec (le jugement, lui, est déjà PAYÉ — ce
  // n'est pas lui qu'on rejoue) rouvrait donc une conversation d'écart
  // CHAQUE NUIT, indéfiniment, sans jamais consommer la moindre
  // tentative ni atteindre un état terminal. Même garde que ses sœurs
  // (skip si déjà >= maxAttempts) ET statut terminal du marqueur
  // (`application-abandoned`, ci-dessous) pour qu'un futur passage de
  // `readJudgeLocalMarkersForDate` ne le reclasse plus jamais en
  // `pendingReplays`.
  if (candidate.attempts >= cfg.localJudge.maxAttempts) {
    outcomes.push(
      `${candidate.id} : verdict rejoué en attente d'application déjà abandonné (>= maxAttempts=${cfg.localJudge.maxAttempts}) — marqueur neutralisé`,
    );
    await writeJudgeLocalMarker(replay.markerPath, candidate.id, 'application-abandoned');
    continue;
  }

  await touchLock();
  try {
    await applyResultSideEffects(replay.item);
    successCount++;
    outcomes.push(
      `${candidate.id} : verdict rejoué depuis le marqueur (crash précédent avant application) — appliqué avec succès, aucun nouveau coût`,
    );
    // Fix P3 (rétention, round 2 — "judge-local-markers grandit sans
    // fin") : le verdict n'est plus embarqué une fois APPLIQUÉ — plus
    // aucun usage (seuls les marqueurs encore `verdict-obtained` sont
    // relus pour un rejeu), inutile de le laisser grossir le disque.
    await writeJudgeLocalMarker(replay.markerPath, candidate.id, 'applied');
  } catch (err) {
    failureCount++;
    const detail = (err as Error).message;
    const newAttempts = await recordJudgeLocalFailure(candidate, detail);
    gaps.push(
      `${candidate.id} (${candidate.kind}, skill ${candidate.skill}) : verdict rejoué depuis le marqueur mais application encore en échec — ${detail}`,
    );
    outcomes.push(
      `${candidate.id} : verdict rejoué depuis le marqueur mais application encore en échec — ${detail}` +
        (newAttempts === undefined ? ' (ATTENTION : compteur localJudgeAttempts NON incrémenté)' : ''),
    );
    if (newAttempts !== undefined) {
      candidate.attempts = newAttempts;
      // Terminal DÈS que le seuil est franchi — sans quoi ce même
      // marqueur resterait `verdict-obtained` et serait retenté (et
      // reconnu comme un nouvel échec, gaps rouverts) la nuit suivante,
      // malgré `noteAbandonmentIfJustCrossed` ci-dessous qui ne signale
      // le franchissement qu'UNE fois.
      if (newAttempts >= cfg.localJudge.maxAttempts) {
        await writeJudgeLocalMarker(replay.markerPath, candidate.id, 'application-abandoned');
      }
    }
    // Fix P2 (revue adversariale round 3, l.2775-2802 — même finding que
    // ci-dessus) : cet appel manquait ICI avant ce fix (présent sur
    // TOUTES les autres boucles d'échec de ce fichier) — sans lui, ni le
    // message d'abandon "franchissement du seuil" ni le routage
    // `newAttempts === undefined` vers `gaps` (voir sa docstring) ne
    // s'appliquaient jamais aux rejeux.
    noteAbandonmentIfJustCrossed(gaps, candidate.id, candidate.kind, candidate.skill, newAttempts, cfg.localJudge.maxAttempts);
  }
}

